/* Annotated source reader. Data comes from source-data.js (generated by tools/guide/build.py). */
(function () {
  "use strict";

  const DATA = (window.FORGE_SOURCE && window.FORGE_SOURCE.files) || [];
  const GROUPS = ["Shell core", "Job control", "Observability", "Headers", "Build & tests", "Demo programs"];
  const listEl = document.getElementById("filelist");
  const main = document.getElementById("listing");
  const filter = document.querySelector(".filter");

  const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const span = (cls, s) => `<span class="${cls}">${esc(s)}</span>`;

  /* ---------------- highlighting ---------------- */

  const C_KW = new Set("if else while for do return break continue switch case default goto sizeof typedef struct enum union static extern const volatile inline register void char short int long float double signed unsigned bool true false NULL".split(" "));
  const C_TYPES = /^(?:[a-z_]+_t|FILE|DIR|Job|Process|Command|JobPipeline|ShellState|ProcInfo|Token|TokenList|TokenType|JobState)$/;

  function highlightC(lines) {
    let inComment = false;
    return lines.map((line) => {
      let out = "", i = 0;
      const trimmed = line.trimStart();
      if (!inComment && trimmed.startsWith("#")) {
        const lead = line.length - trimmed.length;
        const m = trimmed.match(/^(#\s*\w+)(.*)$/);
        if (m) {
          let rest = m[2], restHtml = "";
          const cm = rest.indexOf("/*");
          if (cm >= 0) { restHtml = esc(rest.slice(0, cm)) + span("tk-c", rest.slice(cm)); if (!rest.includes("*/", cm)) inComment = true; }
          else restHtml = rest.replace(/("[^"]*"|<[^>]*>)|([^"<]+)/g, (all, str, other) => str ? span("tk-s", str) : esc(other));
          return esc(line.slice(0, lead)) + span("tk-p", m[1]) + restHtml;
        }
      }
      const atCol0 = line.length > 0 && !/^\s/.test(line);
      while (i < line.length) {
        const rest = line.slice(i);
        if (inComment) {
          const end = rest.indexOf("*/");
          if (end < 0) { out += span("tk-c", rest); i = line.length; }
          else { out += span("tk-c", rest.slice(0, end + 2)); i += end + 2; inComment = false; }
          continue;
        }
        let m;
        if (rest.startsWith("/*")) { inComment = true; continue; }
        if (rest.startsWith("//")) { out += span("tk-c", rest); break; }
        if ((m = rest.match(/^"(?:\\.|[^"\\])*"?/))) { out += span("tk-s", m[0]); i += m[0].length; continue; }
        if ((m = rest.match(/^'(?:\\.|[^'\\])*'?/))) { out += span("tk-s", m[0]); i += m[0].length; continue; }
        if ((m = rest.match(/^\d[\w.]*/))) { out += span("tk-n", m[0]); i += m[0].length; continue; }
        if ((m = rest.match(/^[A-Za-z_]\w*/))) {
          const w = m[0];
          const after = rest.slice(w.length);
          if (C_KW.has(w)) out += span("tk-k", w);
          else if (C_TYPES.test(w)) out += span("tk-t", w);
          else if (atCol0 && /^\s*\(/.test(after)) out += span("tk-f", w);
          else out += esc(w);
          i += w.length;
          continue;
        }
        out += esc(line[i]);
        i++;
      }
      return out;
    });
  }

  const PY_KW = new Set("def return if elif else for while in not and or import from as try except raise assert with global pass break continue None True False lambda class is yield".split(" "));
  function highlightPy(lines) {
    let inTriple = null;
    return lines.map((line) => {
      let out = "", i = 0;
      while (i < line.length) {
        const rest = line.slice(i);
        if (inTriple) {
          const end = rest.indexOf(inTriple);
          if (end < 0) { out += span("tk-s", rest); i = line.length; }
          else { out += span("tk-s", rest.slice(0, end + 3)); i += end + 3; inTriple = null; }
          continue;
        }
        let m;
        if ((m = rest.match(/^[fr]?("""|''')/))) { inTriple = m[1]; out += span("tk-s", m[0]); i += m[0].length; continue; }
        if (rest.startsWith("#")) { out += span("tk-c", rest); break; }
        if ((m = rest.match(/^[fr]?"(?:\\.|[^"\\])*"?/)) || (m = rest.match(/^[fr]?'(?:\\.|[^'\\])*'?/))) { out += span("tk-s", m[0]); i += m[0].length; continue; }
        if ((m = rest.match(/^\d[\w.]*/))) { out += span("tk-n", m[0]); i += m[0].length; continue; }
        if ((m = rest.match(/^[A-Za-z_]\w*/))) {
          const w = m[0];
          if (PY_KW.has(w)) out += span("tk-k", w);
          else if (/\bdef\s+$/.test(line.slice(0, i))) out += span("tk-f", w);
          else out += esc(w);
          i += w.length;
          continue;
        }
        out += esc(line[i]);
        i++;
      }
      return out;
    });
  }

  function highlightMake(lines) {
    return lines.map((line) => {
      if (/^\s*#/.test(line)) return span("tk-c", line);
      let html = esc(line);
      html = html.replace(/\$\([^)]*\)|\$[@<^]/g, (v) => `<span class="tk-t">${v}</span>`);
      const m = line.match(/^([A-Za-z_][\w]*)(\s*)(\?=|\+=|:=|=)/);
      if (m) html = html.replace(esc(m[1]), `<span class="tk-k">${esc(m[1])}</span>`);
      else if (/^[^\s=#][^=]*:(?!=)/.test(line)) {
        const idx = html.indexOf(":");
        html = `<span class="tk-f">${html.slice(0, idx)}</span>${html.slice(idx)}`;
      }
      return html;
    });
  }

  function highlightYaml(lines) {
    return lines.map((line) => {
      if (/^\s*#/.test(line)) return span("tk-c", line);
      let html = esc(line);
      html = html.replace(/^(\s*-?\s*)([\w-]+)(:)/, (all, a, k, c) => `${a}<span class="tk-k">${k}</span>${c}`);
      html = html.replace(/\$\{\{[^}]*\}\}/g, (v) => `<span class="tk-t">${v}</span>`);
      html = html.replace(/(&quot;|")[^"]*\1|'[^']*'/g, (v) => `<span class="tk-s">${v}</span>`);
      return html;
    });
  }

  function highlight(file) {
    if (file.lang === "python") return highlightPy(file.lines);
    if (file.lang === "make") return highlightMake(file.lines);
    if (file.lang === "yaml") return highlightYaml(file.lines);
    return highlightC(file.lines);
  }

  /* ---------------- file list ---------------- */

  function buildList(q) {
    listEl.replaceChildren();
    const ql = (q || "").toLowerCase();
    GROUPS.forEach((g) => {
      const files = DATA.filter((f) => f.group === g && (!ql || f.path.toLowerCase().includes(ql) || f.title.toLowerCase().includes(ql)));
      if (!files.length) return;
      const h = document.createElement("h5");
      h.textContent = g;
      listEl.appendChild(h);
      files.forEach((f) => {
        const a = document.createElement("a");
        a.href = "#" + f.path;
        a.textContent = f.path;
        a.title = f.title;
        a.dataset.path = f.path;
        listEl.appendChild(a);
      });
    });
    markCurrent();
  }
  function markCurrent() {
    listEl.querySelectorAll("a").forEach((a) => a.setAttribute("aria-current", a.dataset.path === current ? "true" : "false"));
  }
  filter.addEventListener("input", () => buildList(filter.value));

  /* ---------------- listing ---------------- */

  let current = null;
  const cache = new Map();

  function parseHash() {
    let h = decodeURIComponent(location.hash.slice(1));
    if (!h) return { path: DATA[0] && DATA[0].path };
    let path = h, line = null, text = null;
    const at = h.indexOf("@");
    if (at >= 0) { path = h.slice(0, at); text = h.slice(at + 1); }
    else {
      const m = h.match(/^(.*):(\d+)$/);
      if (m) { path = m[1]; line = +m[2]; }
    }
    return { path, line, text };
  }

  function render() {
    const { path, line, text } = parseHash();
    const file = DATA.find((f) => f.path === path) || DATA[0];
    if (!file) { main.textContent = "No source data found."; return; }
    let target = line;
    if (text) {
      const idx = file.lines.findIndex((l) => l.includes(text));
      if (idx >= 0) target = idx + 1;
    }
    if (current !== file.path) {
      current = file.path;
      draw(file);
      markCurrent();
      document.title = file.path + " \u00b7 ForgeShell source";
      if (!target) window.scrollTo({ top: 0 });
    }
    main.querySelectorAll(".line.target").forEach((n) => n.classList.remove("target"));
    if (target) {
      const block = file.blocks.find((b) => target >= b.start && target <= b.end);
      const node = block && main.querySelector(`[data-start="${block.start}"]`);
      const ln = main.querySelector(`[data-line="${target}"]`);
      if (ln) ln.classList.add("target");
      if (node) {
        node.classList.remove("flash");
        void node.offsetWidth;
        node.classList.add("flash");
        const y = node.getBoundingClientRect().top + window.scrollY - 76;
        window.scrollTo({ top: y, behavior: "smooth" });
      }
    }
  }

  function draw(file) {
    if (!cache.has(file.path)) cache.set(file.path, highlight(file));
    const hl = cache.get(file.path);
    const idx = DATA.indexOf(file);
    const prev = DATA[idx - 1], next = DATA[idx + 1];
    const parts = [];
    parts.push(`<header class="listing-head"><div class="path">${esc(file.path)}</div><h1>${esc(file.title)}</h1><div class="meta">${file.lines.length} lines &middot; ${file.blocks.length} notes &middot; ${esc(file.group)} &middot; <a href="https://github.com/JeyaVardhan-L/ForgeShell/blob/main/${encodeURI(file.path)}">view on GitHub</a></div></header>`);
    file.blocks.forEach((b) => {
      const code = [];
      for (let n = b.start; n <= b.end; n++) {
        code.push(`<span class="line" data-line="${n}"><a class="ln" href="#${esc(file.path)}:${n}" tabindex="-1">${n}</a>${hl[n - 1] || " "}</span>`);
      }
      const range = b.start === b.end ? `LINE ${b.start}` : `LINES ${b.start}\u2013${b.end}`;
      parts.push(`<section class="block" data-start="${b.start}"><pre class="code"><code>${code.join("")}</code></pre><div class="note"><div class="note-inner"><span class="range">${range}</span>${b.html}</div></div></section>`);
    });
    parts.push(`<nav class="pager">${prev ? `<a href="#${esc(prev.path)}">\u2190 ${esc(prev.path)}</a>` : "<span></span>"}${next ? `<a href="#${esc(next.path)}">${esc(next.path)} \u2192</a>` : "<span></span>"}</nav>`);
    main.innerHTML = parts.join("");
    main.querySelectorAll(".ln").forEach((a) => a.style.textDecoration = "none");
  }

  window.addEventListener("hashchange", render);
  buildList("");
  render();
})();
